/**
 * @file utility-serialize.ts
 * @copyright 2024-2026, Firaxis Games
 * @description Provides a "catalog" to Store and retrieve arbitrary key/values for the world or per-player.
 *
 *	TWO MODES
 * 	A catalog will behave in one of two ways: as a "world" catalog or "player" catalog.
 *	Which mode is set by the constructor.  If a player is provided, it will be a player catalog, otherwise it will be a world catalog.
 *	World catalogs are local only, but their values can be immediately read back after writing.
 *	Player catalogs are written to the cache via player operation, and so you must wait until the value is committed before reading it back.
 *	You CANNOT write values for other players if it's not their turn! (The player operation code in the App will say, "not your turn" and ignore the write.)
 *
 *	OFFERS
 *	- A way to store and retrieve simple typed value using a key (string).
 * 	- Scoping of one level deep of objects with multiple properties.
 * 	- Has a mechanism to enumerate the keys written.
 * 	- Has a mechanism to signal when a value is committed.
 *
 *	UNDER THE HOOD
 *	There is just a flat list (per-player) of key/value pairs.
 *	The actual key is a uint32 which is a hash of the catalog name, object name, and property name.
 *
 *	IN SUMMARY
 *	A top level "catalog" object tracks all the objects in the store.
 *	Each object can have multiple properties read/writen
 *
 *	LAYOUT EXAMPLE
 *	Full Key (as string):			Data:								Description
 * 	------------------------------- ----------------------------------- ---------------------
 *	_MyStuff__KEYS					<objid1>,<objid2>, ... ,<objidN>	Comma separated list of objects in this catalog by their ID.
 *	_MyStuff_OBJ_<objid1>_KEYS		<key1>,<key2, ... ,<keyN>			Comma separated list of properties for object 1 by their key.
 *	_MyStuff_OBJ_<objid1>_<key1>	<value1>							key and value of first item on this object
 *	_MyStuff_OBJ_<objid1>_<key2>	<value2>
 * :
 *	_MyStuff_OBJ_<objid1>_<keyN>	<valueN>
 *	_MyStuff_OBJ_<objid2>_KEYS		<key1>,<key2, ... ,<keyN>
 *	_MyStuff_OBJ_<objid2>_<key1>	<value1>
 *	_MyStuff_OBJ_<objid2>_<key2>	<value2>
 * :
 *	_MyStuff_OBJ_<objid2>_<keyN>	<valueN>
 * :
 * :
 *	_MyStuff_OBJ_<objidN>_KEYS		<key1>,<key2, ... ,<keyN>
 *	_MyStuff_OBJ_<objidN>_<key1>	<value1>
 *	_MyStuff_OBJ_<objidN>_<key2>	<value2>
 * :
 * _MyStuff_OBJ_<objidN>_<keyN>		<valueN>
 *
 * @usage
 * // World Exanmple
 * const catalog = new Catalog({name:"GeneralStuff", version: 1234});
 * const obj = catalog.getObject("foo");
 * const old = obj.read("someStuff") as string;
 * obj.write("someOtherStuff","crabcakes are delicious")
 *
 * // Player Example
 * // Setup callback first, this will get signaled when the value is committed from the cache.
 *	window.addEventListener(CatalogItemCommittedEventName, (event: CatalogItemCommittedEvent) => {
 *		if (event.detail.catalogId === "MyStuff" && event.detail.objectId === "fireworks" && event.detail.key === "sparklers") {
 *			const newAmount = fireworks.read("sparklers") as number;
 *			console.log(`new amount: ${newAmount}`);
 *		}
 *	});
 * // Now read existing values and throw to the cache any values to be written.
 *	const myCatalog = new Catalog({ name: "MyStuff", version: 1, player: Players.get(GameContext.localPlayerID) });
 *	const fireworks = myCatalog.getObject("fireworks");
 *	const num = (fireworks.read("sparklers") as number) ?? 0;
 *	fireworks.write("sparklers", num + 1);
 */

const DEBUG_LOG_META_INFO = false; // (false) if the meta information should be logged out
const DEBUG_LOG_WRITES = false; // (false) log out what is being written to disk
const DEBUG_LOG_READS = false; // (false) log out what is being read in from disk
const DEBUG_LOG_COMMITS = false; // (false) log out when commit from cache to active values happen in gamecore
const DEBUG_LOG_LAST_COMMIT = false; // (false) log out the last commit from the cache
const DEBUG_RUN_TEST = false; // (false) true to run the unit test when entering the game.  See bottom of file for details.
const CATALOG_FORMAT_VERSION = 3; // Version of the underlying data used by the catalog itself.

/** Types allowed to be serialized. */
export type SerializeType = string | number | boolean;

// ====================================================================
//	Internal Helper Utilities
// ====================================================================

/// Create a hash based on a preamble and key.
function makeHash(preamble: string, key: string): HashId {
	return Database.makeHash(preamble + key);
}

/// Actual application read from either global store or player store.
function internalRead(player: PlayerLibrary | null, hash: HashId): SerializeType {
	return player != null ? player.Tutorial!.getProperty(hash) : GameTutorial.getProperty(hash);
}

/// Actual application write from either global store or player store.
function internalWrite(player: PlayerLibrary | null, hash: HashId, value: SerializeType) {
	if (!player) {
		GameTutorial.setProperty(hash, value);
	} else {
		player.Tutorial!.setProperty(hash, value);
	}
}

/// Enumerated set of values off of special "KEYS" property for a given object.
function loadKeys(player: PlayerLibrary | null, preamble: string): Set<string> {
	const hash = makeHash(preamble, "KEYS");
	const ids = internalRead(player, hash);
	return typeof ids === "string" && ids.length > 0 ? new Set(ids.split(",")) : new Set();
}

/// Saving of keys to the special "KEYS" property so enumeration can occur.
function saveKeys(player: PlayerLibrary | null, preamble: string, keys: Set<string>) {
	const hash = makeHash(preamble, "KEYS");
	internalWrite(player, hash, Array.from(keys).join(","));
}

// ====================================================================
//	Serialization Object
// ====================================================================

/**
 * An object for reading/writing a group of properties.
 */
export class SerialObject {
	private readonly hashPreamble: string; // preamble for all keys in this object (e.g. "_MyStuff_OBJ_<objid>_")
	private propertyKeys: Set<string>; // track keys written to this object for enumeration
	private hashCache: Map<string, HashId> = new Map<string, HashId>(); // saved hash values for fast lookup

	/**
	 * CTOR
	 * @param id name of the object
	 * @param scope name used as part of the hash
	 * @param catalogId untouched catalog id needed for tracking
	 * @param player (null) set to a Player if not a world catalog
	 */
	constructor(
		private readonly id: string,
		private readonly scope: string,
		private readonly catalogId: string,
		private readonly player: PlayerLibrary | null = null,
	) {
		this.hashPreamble = "_" + scope + "_" + id + "_";
		this.propertyKeys = loadKeys(this.player, this.hashPreamble);

		// Pre-populate the cache with the hashes of all existing keys.
		for (const key of this.propertyKeys) {
			this.hashCache.set(key, makeHash(this.hashPreamble, key));
		}
	}

	/**
	 * Retrieves the hash for a key if it exists.
	 * If not, generate the hash, save it, and return it.
	 */
	private getCachedHash(key: string): HashId {
		let hash = this.hashCache.get(key);
		if (hash === undefined) {
			hash = makeHash(this.hashPreamble, key);
			this.hashCache.set(key, hash);
		}
		return hash;
	}

	/**
	 * @returns a collection of IDs maintained by this object.
	 */
	public getKeys(): Set<string> {
		return this.propertyKeys;
	}

	/**
	 * DEBUG Helper
	 * @returns a comma-separated lsit of IDs maintained by this object.
	 */
	private getKeysAsString(): string {
		return [...this.propertyKeys].join(", ");
	}

	/**
	 * Read a single value.
	 * @returns the value for the given key, or undefined if not existing.
	 */
	read(key: string): SerializeType {
		const hash: HashId = this.getCachedHash(key);
		const value = internalRead(this.player, hash);
		if (DEBUG_LOG_READS) {
			console.log(
				`Catalog: (READ)  '${key}'(${hash}) = '${value}', player: ${this.player ? this.player.id : "*"}, key='${this.hashPreamble + key}'`,
			);
		}
		return value;
	}

	/**
	 * Request a write of a single value.
	 * If the global store, the write happens immediate.
	 * If a player store, the write is queued to be committed by the cache.
	 * The commited value is signaled from the App side by an event.
	 */
	write(key: string, value: SerializeType) {
		const hash: HashId = this.getCachedHash(key);
		if (DEBUG_LOG_WRITES) {
			console.log(
				`Catalog: (WRITE) '${key}'(${hash}) = '${value}', player: ${this.player ? this.player.id : "*"}, key='${this.hashPreamble + key}'`,
			);
		}
		internalWrite(this.player, hash, value);

		// Support enumeration by tracking which keys were written to special "KEYS" property.
		if (!this.propertyKeys.has(key)) {
			this.propertyKeys.add(key);
			saveKeys(this.player, this.hashPreamble, this.propertyKeys);
		}

		// Support event callbacks if this is a player catalog.
		if (this.player) {
			addTrackingEntry(this.player.id, hash, this.catalogId, this.id, key);
		}
	}
}

// ====================================================================
//	Catalog Object
// ====================================================================

export interface CatalogProperties {
	name: string; // ID of the catalog
	version?: number; // verion of the information stored in the catalog (specific to the system saving it)
	player?: PlayerLibrary | null; // If set, uses a player-specific store, otherwise uses a global store (with immediate writes).
}

/**
 * Top level class that maintains the catalog of serial objects.
 */
export class Catalog {
	public readonly name: string;

	private _player: PlayerLibrary | null = null;
	private _fileVersion = 0;
	private _runningVersion = 0;
	private _justCreated = false;

	private readonly hashPreamble: string;
	private objectIDs: Set<string>;

	public get fileVersion(): number {
		return this._fileVersion;
	}
	public get runningVersion(): number {
		return this._runningVersion;
	}
	public get justCreated(): boolean {
		return this._justCreated;
	}

	/**
	 * CTOR
	 */
	constructor(properties: CatalogProperties) {
		this.name = properties.name;
		this._player = properties.player ?? null;
		this._runningVersion = properties.version ?? 0;
		this.hashPreamble = "_" + this.name + "__";
		this.objectIDs = loadKeys(this._player, this.hashPreamble);

		this.realizeInfoBlock(this._runningVersion);

		// Only setup the event listener if this is a player catalog, since world catalogs are immediate.
		if (this._player != null) {
			engine.on("PlayerDynamicPropertyChanged", this.onPlayerDynamicPropertyChanged, this);
		}
	}

	/**
	 * If a catalog ever needs to be explicitly cleaned up; call this.
	 */
	public dispose() {
		if (this._player != null) {
			engine.off("PlayerDynamicPropertyChanged", this.onPlayerDynamicPropertyChanged, this);
		}
	}

	/** Names of the objects stored in the catalog */
	public getObjectIds(): Set<string> {
		return this.objectIDs;
	}

	private onPlayerDynamicPropertyChanged(data: PlayerDynamicPropertyChanged_EventData) {
		const trackingResult = removeTrackingEntry(data.player, data.keyHash);
		if (trackingResult.amount === 0) {
			window.dispatchEvent(
				new CatalogItemCommittedEvent(
					data.player,
					data.keyHash,
					trackingResult.catalogId,
					trackingResult.objectId,
					trackingResult.key,
				),
			);
		}
		if (DEBUG_LOG_COMMITS) {
			console.log(
				`Catalog: (COMMIT) '${this.name}' cache for player ${data.player} commited ${data.keyHash} = "${trackingResult.key}".`,
			);
		}
	}

	private realizeInfoBlock(version: number) {
		if (DEBUG_LOG_META_INFO) {
			console.log(`Catalog: '${this.name}' realizing info block. version: ${version}`);
		}

		const info = new SerialObject("INFO", this.name, this.name, this._player);
		const diskVersion = info.read("version") as number;
		this._justCreated = diskVersion === undefined;
		this._fileVersion = this._justCreated ? version : diskVersion;

		if (DEBUG_LOG_META_INFO) {
			console.log(`Catalog: '${this.name}' diskVersion: ${diskVersion}`);
			console.log(`Catalog: '${this.name}' justCreated: ${this._justCreated}`);
			console.log(`Catalog: '${this.name}' fileVersion: ${this._fileVersion}`);
		}

		if (this._justCreated) {
			info.write("version", version);
			info.write("first_version", version);
			info.write("catalog_format", CATALOG_FORMAT_VERSION);
			info.write("created", Date.now());
			info.write("hosting", Network.getLocalHostingPlatform());

			if (DEBUG_LOG_META_INFO) {
				console.log(`Catalog: '${this.name}' is NEW -------------------------- `);
				console.log(`Catalog: '${this.name}'        version: ${version}`);
			}
		} else {
			if (DEBUG_LOG_META_INFO) {
				console.log(`Catalog: '${this.name}' is old -------------------------- `);
				console.log(`Catalog: '${this.name}'  diskVersion: ${diskVersion}`);
			}

			if (diskVersion < version) {
				console.log(
					`utility-serialize: Catalog object '${this.name}' in save file is ${diskVersion}, app wants ${version}.`,
				);
				info.write("version", version);
			} else if (diskVersion > version) {
				console.warn(
					`utility-serialize: Catalog object '${this.name}' file version is NEWER than app.  File is ${diskVersion}, app is ${version}.`,
				);
			}
		}
	}

	getObject(id: string): SerialObject {
		if (!this.exists(id)) {
			this.objectIDs.add(id);
			saveKeys(this._player, this.hashPreamble, this.objectIDs);
		}
		return new SerialObject(id, this.name + "_OBJ", this.name, this._player);
	}

	exists(id: string): boolean {
		return this.objectIDs.has(id);
	}

	/**
	 * DEBUG Helper
	 * Outputs the entire contents of the catalog to the console as an ASCII tree.
	 * Flags values with "(PENDING #)" if they have outstanding cache commits.
	 */
	public dumpToLog() {
		const lines: string[] = [];
		lines.push(this.name); // Top of the tree is the catalog name.

		// Helper to fetch pending cache entry count for a given hash.
		const getPendingCount = (hash: HashId): number => {
			if (!this._player) return 0;
			const entries = pendingCommits.get(this._player.id);
			if (!entries) return 0;

			const entry = entries.find((e) => e.hash === hash);
			return entry ? entry.outstanding : 0;
		};

		// Helper to format values based on type, key, and pending status
		const formatVal = (key: string, val: SerializeType, hash: HashId): string => {
			const pendingCount = getPendingCount(hash);
			const pendingPrefix = pendingCount > 0 ? `(PENDING ${pendingCount}) ` : "";

			if (val === undefined || val === null) return `${pendingPrefix}undefined`;

			// Special handling for the 'created' timestamp
			if (key === "created") {
				// Coerce to a number in case the cache serialized it as a string
				const dateNum = Number(val);
				if (!isNaN(dateNum)) {
					return `${pendingPrefix}${new Date(dateNum).toLocaleString()}`; // No $ or # prefix
				}
			}

			if (typeof val === "number") return `${pendingPrefix}#${val}`;
			if (typeof val === "string") return `${pendingPrefix}$${val}`;
			return `${pendingPrefix}${String(val)}`; // Booleans get no prefix
		};

		// Gather tree branches
		const info = new SerialObject("INFO", this.name, this.name, this._player);
		const infoPreamble = "_" + this.name + "_INFO_";

		// Explicitly request these keys in case the underlying KEYS string is missing them
		const explicitInfoKeys = ["version", "first_version", "catalog_format", "created", "hosting"];

		// Merge the explicit keys with any other keys that might actually be tracked in the set
		const infoKeysToDump = Array.from(new Set([...explicitInfoKeys, ...info.getKeys()]));
		const objIds = Array.from(this.objectIDs);

		const hasInfo = infoKeysToDump.length > 0;
		const hasObj = objIds.length > 0;

		// 1. Gather the INFO (meta-information).
		if (hasInfo) {
			const infoPrefix = hasObj ? "|-- " : "\\-- ";
			lines.push(`${infoPrefix}INFO`);
			const childIndent = hasObj ? "|   " : "    ";

			infoKeysToDump.forEach((key, index) => {
				const isLast = index === infoKeysToDump.length - 1;
				const branch = isLast ? "\\-- " : "|-- ";
				const hash = makeHash(infoPreamble, key);
				lines.push(`${childIndent}${branch}${key}: ${formatVal(key, info.read(key), hash)}`);
			});
		}

		// 2. Gather the key value pairs, scoped by "objects".
		if (hasObj) {
			objIds.forEach((id, index) => {
				const isLastObj = index === objIds.length - 1;
				const objBranch = isLastObj ? "\\-- " : "|-- ";
				lines.push(`${objBranch}${id}`);

				const obj = this.getObject(id);
				const objPreamble = "_" + this.name + "_OBJ_" + id + "_";
				const keys = Array.from(obj.getKeys());
				const keyIndent = isLastObj ? "    " : "|   ";

				keys.forEach((key, keyIndex) => {
					const isLastKey = keyIndex === keys.length - 1;
					const keyBranch = isLastKey ? "\\-- " : "|-- ";
					const hash = makeHash(objPreamble, key);
					lines.push(`${keyIndent}${keyBranch}${key}: ${formatVal(key, obj.read(key), hash)}`);
				});
			});
		}

		// Output the lines to the console.
		console.log(lines.join("\n"));
	}
}

// ====================================================================
// 	Entry Tracking for Player-based writes
// ====================================================================

/**
 * CatalogItemCommittedEvent is triggered when a catalog item is committed.
 */
export interface CatalogItemCommittedEventDetail {
	playerId: PlayerId;
	hash: HashId;
	catalogId: string;
	objectId: string;
	key: string;
}

export const CatalogItemCommittedEventName = "catalog-item-committed" as const;

export class CatalogItemCommittedEvent extends CustomEvent<CatalogItemCommittedEventDetail> {
	constructor(playerId: PlayerId, hash: HashId, catalogId: string, objectId: string, key: string) {
		super(CatalogItemCommittedEventName, { bubbles: false, detail: { playerId, hash, catalogId, objectId, key } });
	}
}

/**
 * Use to track entries to be committed.
 */
interface TrackingEntry {
	hash: HashId;
	catalogId: string;
	objectId: string;
	key: string;
	outstanding: number;
}

/** Written property entries waiting for confirmation from the App that they have been committed from the cache. */
const pendingCommits: Map<PlayerId, TrackingEntry[]> = new Map<PlayerId, TrackingEntry[]>();

function getEntries(playerId: PlayerId): TrackingEntry[] {
	if (!pendingCommits.has(playerId)) {
		pendingCommits.set(playerId, []);
	}
	return pendingCommits.get(playerId)!;
}

export function addTrackingEntry(playerId: PlayerId, hash: HashId, catalogId: string, objectId: string, key: string) {
	const entries = getEntries(playerId);
	const entry = entries.find((e) => e.hash === hash);
	if (entry) {
		entry.outstanding++;
	} else {
		entries.push({ hash, catalogId, objectId, key, outstanding: 1 });
	}
}

interface TrackingResult {
	amount: number;
	catalogId: string;
	objectId: string;
	key: string;
}

/**
 * Remove a tracking entry for a player and hash.
 * @param playerId The ID of the player for whom to remove the tracking entry.
 * @param hash Hash of kru for which to remove the tracking entry.
 * @returns An object containing the remaining amount and the key.
 */
export function removeTrackingEntry(playerId: PlayerId, hash: HashId): TrackingResult {
	const entries = getEntries(playerId);
	const entryIndex = entries.findIndex((e) => e.hash === hash);
	if (entryIndex !== -1) {
		const entry = entries[entryIndex];
		entry.outstanding--;
		if (entry.outstanding <= 0) {
			if (DEBUG_LOG_LAST_COMMIT && !DEBUG_LOG_COMMITS) {
				console.log(
					`Catalog: (COMMIT) Last write for player ${playerId} commited "${hash}", key='${entry.key}'`,
				);
			}
			entries.splice(entryIndex, 1);
		}
		return { amount: entry.outstanding, catalogId: entry.catalogId, objectId: entry.objectId, key: entry.key };
	}
	return { amount: -1, catalogId: "", objectId: "", key: "" };
}

// ====================================================================
// 	Unit Test(s)
//	To run, set DEBUG_RUN_TEST to true and enter the game.
// ====================================================================
if (DEBUG_RUN_TEST) {
	if (UI.isInGame()) {
		// Tests out writing to a player store and waiting for the commit event to be signaled back to the UI.
		window.addEventListener(CatalogItemCommittedEventName, (event: CatalogItemCommittedEvent) => {
			const details = event.detail;
			console.log(
				`Catalog: (TEST) Event: catalog="${details.catalogId}", object="${details.objectId}", key="${details.key}",  (${details.hash}) for player ${details.playerId}`,
			);
			if (
				details.catalogId === "BoomCatalog" &&
				details.objectId === "fireworks" &&
				details.key === "sparklers"
			) {
				const newAmount = fireworks.read("sparklers") as number;
				console.log("Catalog: (TEST) AFTER commit event...");
				console.log(`Catalog: (TEST) new amount = ${newAmount}`);
				myCatalog.dumpToLog();
			}
		});
		const myCatalog = new Catalog({
			name: "BoomCatalog",
			version: 1,
			player: Players.get(GameContext.localPlayerID),
		});
		const fireworks = myCatalog.getObject("fireworks");
		const num = (fireworks.read("sparklers") as number) ?? 0;
		fireworks.write("sparklers", num + 1);
		console.log("Catalog: (TEST) BEFORE commit event...");
		console.log(`Catalog: (TEST) old amount = ${fireworks.read("sparklers") as number}`);
		myCatalog.dumpToLog();
	}
}
